export function parseGuests(markdown: string): Array<{ name: string; role: string; bio: string }> {
  return [...markdown.matchAll(/^- \*\*(.+?)\s*[｜|]\s*(.+?)\*\*[：:]\s*(.+)$/gm)].map(match => /主持人|觀察者|專家|藝人|當事人/.test(match[1]) ? { name: match[2].trim(), role: match[1].trim(), bio: match[3].trim() } : { name: match[1].trim(), role: match[2].trim(), bio: match[3].trim() });
}
export function rosterFor(session: CoffeeSession, markdown: string): Array<{ name: string; role: string; bio: string }> {
  const zh = session.language === "zh-TW", settings = session.guests;
  const people = [...new Map(parseGuests(markdown).map(person => [person.name.trim().toLocaleLowerCase(), person])).values()];
  const roles = [{ category: "host", en: "Host", zh: "主持人", count: settings?.hostCount ?? 2 }, { category: "observer", en: "Observer", zh: "觀察者", count: 1 }, ...CATEGORIES.map(item => ({ category: item.id, en: item.en, zh: item.zh, count: settings?.counts[item.id] ?? 0 }))];
  const roleKey = (role: string): string => /主持|host/i.test(role) ? "host" : /觀察|observer/i.test(role) ? "observer" : /跨領域|cross.domain/i.test(role) ? "cross-domain" : /通才|generalist/i.test(role) ? "generalist" : /受影響|當事|affected|lived/i.test(role) ? "affected" : /專家|expert/i.test(role) ? "experts" : "";
  const used = new Map<string, number>(); for (const person of people) { const key = roleKey(person.role); if (key) used.set(key, (used.get(key) ?? 0) + 1); }
  const placeholders = roles.flatMap(item => Array.from({ length: Math.max(0, item.count - (used.get(item.category) ?? 0)) }, (_, index) => ({ name: `${zh ? item.zh : item.en} ${index + 1}`, role: zh ? "即將登場" : "Joining", bio: zh ? "等待人物介紹" : "Waiting for the introduction" })));
  return [...people, ...placeholders];
}
export function liveRosterFor(session: CoffeeSession, draftMarkdown = ""): Array<{ name: string; role: string; bio: string }> {
  const history = [session.transcriptMarkdown, ...(session.rounds ?? []).flatMap(round => [round.markdown, round.draftMarkdown]), ...(session.questions ?? []).flatMap(question => [question.answer, question.draftAnswer])];
  return rosterFor(session, [...history, draftMarkdown].filter(Boolean).join("\n"));
}
export function parseSpeeches(markdown: string): Array<{ name: string; role: string; text: string }> {
  const body = markdown.split(/^# (?:觀察者整理|Observer(?:[’']s)? notes)\s*$/m, 1)[0];
  const people = parseGuests(body), roles = new Map(people.map(person => [person.name, person.role]));
  return [...body.matchAll(/^###\s+([^\n]+)\n([\s\S]*?)(?=^###\s|$(?![\s\S]))/gm)].map(match => {
    const [name, explicitRole] = match[1].split(/[｜|]/, 2).map(value => value.trim()); const person = people.find(entry => entry.name === name);
    return { name, role: explicitRole || person?.role || roles.get(name) || "", text: match[2].trim() };
  }).filter(item => item.text && item.role && !/^(觀察者整理|Observer(?:[’']s)? notes)$/.test(item.name));
}
function defaults(): GuestCounts { return { experts: 4, "cross-domain": 1, generalist: 1, affected: 1 }; }
function total(counts: GuestCounts): number { return Object.values(counts).reduce((sum, count) => sum + count, 0); }
