  private renderBubbles(markdown: string, target: HTMLElement): void { const speeches = parseSpeeches(markdown); if (!speeches.length) { this.renderMarkdown(markdown,target); return; } for (const item of speeches) this.renderSpeech(item.name,item.role,item.text,target); }
