  private renderUserBubble(text: string, target: HTMLElement): void { const article = target.createDiv("ct-message ct-message-user"); article.createDiv({ cls: "ct-avatar ct-user-avatar", text: this.tr("You","你") }); const content = article.createDiv("ct-message-content"); content.createEl("strong", { text: this.tr("You","你") }); this.renderMarkdown(text,content.createDiv("ct-bubble markdown-rendered")); }
  private renderMarkdown(markdown: string, target: HTMLElement): void { const job = MarkdownRenderer.render(this.app,markdown,target,this.store.sessionPath(this.engine?.session.id ?? ""),this).then(() => undefined); this.markdownJobs?.push(job); }
