  private async copySample(): Promise<void> { const source = this.engine?.session; if (!source || !source.id.startsWith("sample-")) return; const copy = createSession(source.topic,this.plugin.settings.cliModel,this.plugin.settings.cliReasoning,source.language,source.guests); copy.status="completed"; copy.transcriptMarkdown=source.transcriptMarkdown; copy.rounds=source.rounds?.map(item=>({...item})) ?? []; copy.observerNotes=[...(source.observerNotes ?? [])]; copy.questions=source.questions.map(item=>({...item,id:crypto.randomUUID()})); await this.store.save(copy); this.attach(copy); }
  private refresh(): void { const engine = this.engine; if (!engine || this.closed) return; if (engine.deleted) { this.returnHome(); return; } const signature = `${engine.session.status}:${engine.busy}:${engine.error}:${engine.session.questions.length}`; if (signature !== this.stateSignature) { this.render(); return; } if (this.renderTimer !== null) return; this.renderTimer = window.setTimeout(() => { this.renderTimer = null; if (!this.engine || this.closed) return; this.refreshLive(); },250); }
