function observerNotes(markdown: string): string { return markdown.match(/^# (?:觀察者整理|Observer(?:[’']s)? notes)[\s\S]*$/m)?.[0] ?? ""; }
function initials(name: string): string { return [...name.replace(/[^\p{L}\p{N}]/gu,"")].slice(0,2).join("") || "•"; }
function avatarColor(name: string): number { let hash=0; for (const char of name) hash=(hash*31+char.codePointAt(0)!)|0; return Math.abs(hash)%8; }
